import{b as e,c as i}from"./chunk-4BI2M3UX.mjs";import{d as a}from"./chunk-7PDLEXWB.mjs";import"./chunk-RIUMFBNJ.mjs";var l=i(a,{children:[e("p",{children:"Buddy is a 3-year-old male Poodle with a soft, curly coat and a personality as bright as his expressive eyes. Rescued from a situation where he didn\u2019t receive the care he deserved, Buddy has flourished at Homeward, showing everyone his lively spirit and loving heart. His cheerful demeanor and eagerness to please make him an absolute joy to be around."}),e("p",{children:"Poodles like Buddy are renowned for their intelligence and adaptability, and he lives up to his breed\u2019s reputation. Buddy is quick to learn and always eager to engage in activities that challenge his sharp mind. He loves playing fetch, learning new tricks, and showing off his playful side. At the same time, Buddy enjoys quiet moments of affection, happily curling up beside his humans after an active day. His friendly and social nature ensures he gets along well with people and other pets, making him a loving companion."}),e("p",{children:"Buddy\u2019s story is one of resilience and hope. He\u2019s ready to leave his past behind and begin a new chapter with a family who will cherish his loving and playful nature. Whether he\u2019s accompanying you on a walk, delighting you with his cleverness, or cuddling on the couch, Buddy will fill your days with happiness and companionship."})]}),h=i(a,{children:[e("p",{children:"Milo is a 2-year-old female Maine Coon with a magnificent, fluffy coat and a personality as grand as her appearance. Rescued from a neglectful environment, Milo has embraced her new life at Homeward with grace and resilience. Her striking amber eyes and confident demeanor captivate everyone she meets, and her affectionate nature has made her a favorite among staff and visitors alike."}),e("p",{children:"Maine Coons like Milo are known for their gentle yet playful personalities, and she is no exception. Milo enjoys exploring her surroundings, whether it\u2019s scaling a cat tree or investigating a sunny windowsill. Despite her adventurous spirit, she\u2019s equally content curling up next to her humans, offering a soft purr as a sign of her appreciation. Her intelligence and curiosity make every interaction with her a delight, and she\u2019s always ready to engage in gentle play or receive affection."}),e("p",{children:"Milo\u2019s journey is a testament to her strength and adaptability. From her uncertain past to her current playful and loving self, she\u2019s ready to start her next chapter with a family who will cherish her. Milo promises to bring warmth, companionship, and a touch of elegance to her forever home."})]}),d=i(a,{children:[e("p",{children:"Oliver is a 1-year-old male Scottish Fold with a plush coat and irresistibly adorable folded ears. Rescued from uncertain circumstances, Oliver\u2019s journey to Homeward has been one of discovery and transformation. Despite his rough beginnings, he quickly adapted to shelter life, charming everyone with his calm demeanor and affectionate nature."}),e("p",{children:"Scottish Folds like Oliver are known for their sweet and laid-back personalities, and he truly embodies these traits. Oliver is a curious yet composed cat who enjoys exploring his surroundings at his own pace. Whether it\u2019s discovering a cozy new spot to nap or observing the world from a windowsill, he loves soaking in his environment. He also adores spending time with his humans, whether it\u2019s during quiet moments of affection or playful interactions with his favorite toys."}),e("p",{children:"Oliver\u2019s story is one of resilience and quiet strength. He\u2019s ready to leave his past behind and start fresh with a family who will appreciate his gentle nature and unique charm. Whether it\u2019s curling up beside you after a long day or playfully batting at a toy mouse, Oliver will bring joy to your home."})]}),c=i(a,{children:[e("p",{children:"Daisy is a 4-year-old female Labrador Retriever with a golden coat and a heart as warm as her gentle eyes. Rescued from a situation where she lacked proper care, Daisy has blossomed at Homeward, showing everyone her loving and resilient nature. Her sweet disposition and eagerness to connect make her an instant favorite among staff, volunteers, and visitors."}),e("p",{children:"Labradors like Daisy are celebrated for their friendly and intelligent personalities, and she lives up to her breed\u2019s reputation in every way. Daisy loves being active, whether it\u2019s chasing a ball, going for walks, or simply running around in the yard. Her playful side is perfectly balanced by her calm and affectionate demeanor, making her an ideal companion for families or individuals seeking a loyal and loving pet. At the end of the day, Daisy enjoys nothing more than curling up beside her humans, basking in their presence and soaking up all the love."}),e("p",{children:"Daisy\u2019s journey is one of transformation and hope. From a timid beginning to a confident, joyful dog, she\u2019s ready to start a new chapter with a family who will cherish her for the wonderful companion she is. Daisy promises to bring boundless love, wagging tails, and happy memories to her forever home."})]}),y=i(a,{children:[e("p",{children:"Max is a 1-year-old male Pug with a big personality packed into his small, sturdy frame. With his expressive eyes, wrinkled face, and signature curly tail, Max is impossible to resist. Rescued from a difficult situation, Max has shown remarkable resilience and quickly adapted to the loving care at Homeward. His playful antics and affectionate nature have made him a favorite at the shelter."}),e("p",{children:"Pugs like Max are known for their friendly and outgoing personalities, and he\u2019s no exception. Max loves being the center of attention, whether it\u2019s during playtime, walks, or snuggling sessions. His goofy charm and silly behavior bring endless laughter and joy to everyone he meets. Despite his playful side, Max also enjoys calm moments where he can relax."}),e("p",{children:"Max\u2019s story is one of resilience and unwavering cheerfulness. He\u2019s ready to leave his past behind and bring his vibrant energy and endless cuddles to a loving forever home. Whether it\u2019s a walk around the block, a game of tug, or a cozy nap by your side, Max will be your loyal companion."})]}),u=i(a,{children:[e("p",{children:"Bella is a 4-year-old female Beagle with soulful eyes and an infectious enthusiasm for life. Rescued from a situation where she didn\u2019t receive the attention she deserved, Bella\u2019s journey to Homeward has been one of incredible resilience and transformation. Her sweet nature and boundless curiosity quickly made her a favorite among the staff and volunteers."}),e("p",{children:"Beagles like Bella are known for their playful energy and strong bond with their families, and she truly embodies the best of her breed. Bella loves exploring her surroundings, following her nose wherever it leads, and discovering new adventures along the way. Whether she\u2019s playing in the yard, going for walks, or simply relaxing at home, Bella thrives on human connection and being part of the action. Despite her playful side, she also has a calm and cuddly nature, making her a versatile companion for active families or those who enjoy cozy evenings in."}),e("p",{children:"Bella\u2019s story is a testament to the love and care that Homeward provides. From a timid dog to a confident and joyful companion, she\u2019s ready to start her next chapter with a family who will cherish her for the loving, playful dog she is. Bella promises to bring endless joy, wagging tails, and unconditional love."})]}),f=i(a,{children:[e("p",{children:"Rocky is a 3-year-old male Siberian cat with a luxurious, thick coat and piercing green eyes that perfectly match his regal and gentle demeanor. Rescued from a challenging situation, Rocky\u2019s journey to Homeward has been one of perseverance and heartwarming transformation. Despite his rough beginnings, he quickly adapted to the loving environment of the shelter, showcasing his affectionate and calm personality to everyone he meets."}),e("p",{children:"Siberian cats like Rocky are known for their friendly and easygoing nature, and he embodies these traits effortlessly. Rocky has a quiet confidence, often seeking out sunny spots to lounge in or perching on a high ledge to observe his surroundings with curiosity and grace. He enjoys gentle play with feather toys but is just as content being the recipient of head rubs and soothing words. His calm and collected demeanor makes him an ideal companion for those seeking a low-maintenance yet loving pet."}),e("p",{children:"Rocky\u2019s story is one of resilience and quiet strength. He\u2019s ready to leave his past behind and find a forever home where he can offer his unwavering loyalty and warmth. Whether it\u2019s curling up beside you during a relaxing evening or playfully batting at a toy, Rocky promises to bring love and tranquility to his new family."})]}),p=i(a,{children:[e("p",{children:"Simba is a 2-year-old female Bichon Frise with a soft, fluffy coat and an endearing personality that instantly wins hearts. Rescued from a neglectful situation, Simba\u2019s journey to Homeward has been one of resilience and newfound joy. She quickly adapted to the loving care of the shelter, blossoming into a playful and affectionate companion. Her warm, expressive eyes reflect her gratitude and readiness to start fresh with a family who will love her unconditionally."}),e("p",{children:"Bichon Frises like Simba are known for their cheerful and adaptable nature, and she lives up to her breed\u2019s reputation as a charming and loving companion. Simba enjoys being the center of attention and thrives on human interaction. Her playful antics\u2014like chasing after a favorite squeaky toy or prancing through the yard\u2014bring smiles to everyone around her. At the end of the day, she\u2019s just as happy curling up next to her favorite person for some quiet bonding time."}),e("p",{children:"Simba\u2019s story is a reminder of the transformative power of love and care. From a timid and uncertain pup to a confident, joyful dog, she\u2019s ready to embark on a new adventure with her forever family. Simba promises to bring light, laughter, and endless cuddles to the lucky home that welcomes her."})]}),g=i(a,{children:[e("p",{children:"Willow is a 1-year-old male Abyssinian cat with a sleek, glossy coat and mesmerizing almond-shaped eyes that reflect his boundless curiosity. Rescued from life as a stray, Willow\u2019s journey to Homeward has been one of transformation and resilience. Despite his early challenges, he has quickly adapted to the comfort and care of shelter life, earning the affection of everyone he meets. His playful energy and adventurous spirit are as captivating as his warm, affectionate personality."}),e("p",{children:"Abyssinians like Willow are often referred to as the \u201Cathletes of the cat world\u201D for their agility, grace, and endless curiosity. True to his breed, Willow spends his days climbing, exploring, and finding joy in the simplest activities. His adventurous nature means there\u2019s never a dull moment when he\u2019s around, but he balances his energy with a tender side. After an active day, Willow loves curling up in a cozy spot or leaning in for affectionate headbutts."}),e("p",{children:"Willow\u2019s story is one of potential waiting to unfold. He has a love for life that\u2019s infectious, and his ability to turn even the smallest experience into an adventure makes him a truly special companion. Whether he\u2019s chasing a toy mouse or watching the world through a sunny window, Willow approaches life with the perfect mix of enthusiasm and grace. He\u2019s ready to leave his past behind and start a new chapter with a family who will love and cherish him as much as he will them."})]}),m=i(a,{children:[e("p",{children:"Cleo is a 6-year-old female Manx with a sweet, affectionate nature and an inspiring story that captures the heart. Found as a stray, she faced significant challenges early in life, but her journey to Homeward marked the beginning of a beautiful transformation. Under the care, love, and compassion of the team, Cleo has flourished, showing incredible resilience and a boundless capacity for love that knows no limits."}),e("p",{children:"Her gentle and loving personality makes her a true joy to be around. Cleo is confident yet warm, and she adores spending quality time with her favorite humans. Whether she\u2019s engaging with her toys or simply curling up for a peaceful nap, her presence brings comfort, warmth, and joy to everyone who has the pleasure of meeting her."}),e("p",{children:"Cleo\u2019s tailless appearance, a distinct signature trait of the Manx breed, adds to her one-of-a-kind charm and beauty. It doesn\u2019t hinder her natural agility or playful spirit\u2014in fact, she thoroughly enjoys exploring her surroundings with endless curiosity and remarkable grace. Her unique combination of resilience, affection, and playful energy makes her truly extraordinary, and she\u2019s ready to share her life with a family who will love and cherish her."})]}),w={exports:{richText4:{type:"variable",annotations:{framerContractVersion:"1"}},richText8:{type:"variable",annotations:{framerContractVersion:"1"}},richText5:{type:"variable",annotations:{framerContractVersion:"1"}},richText3:{type:"variable",annotations:{framerContractVersion:"1"}},richText6:{type:"variable",annotations:{framerContractVersion:"1"}},richText9:{type:"variable",annotations:{framerContractVersion:"1"}},richText2:{type:"variable",annotations:{framerContractVersion:"1"}},richText:{type:"variable",annotations:{framerContractVersion:"1"}},richText1:{type:"variable",annotations:{framerContractVersion:"1"}},richText7:{type:"variable",annotations:{framerContractVersion:"1"}},__FramerMetadata__:{type:"variable"}}};export{w as __FramerMetadata__,l as richText,h as richText1,d as richText2,c as richText3,y as richText4,u as richText5,f as richText6,p as richText7,g as richText8,m as richText9};
